class Exit(GenericExit):
    """Exit command class."""

    def __init__(self, connection, prompt=None, newline_chars=None, runner=None, expected_prompt=r"ute@SC5G.*\$",
                 allowed_newline_after_prompt=False, target_newline="\n", **kwargs):
        """
        Exit from service user state.

        :param connection: moler connection to device, terminal when command is executed
        :param prompt: Prompt of the starting shell
        :param newline_chars: Characters to split lines
        :param runner: runner ro run command
        :param expected_prompt: Prompt of the target shell reached after exit from service user state

        """
        super(Exit, self).__init__(connection=connection, prompt=prompt, newline_chars=newline_chars,
                                   runner=runner, expected_prompt=expected_prompt,
                                   allowed_newline_after_prompt=allowed_newline_after_prompt,
                                   target_newline=target_newline, **kwargs)


COMMAND_OUTPUT = """
serviceuser@5gbts-190-oam-000 [5gbts-190]  > exit
ute@SC5G-eNB-190:~$"""

COMMAND_KWARGS = {
    "expected_prompt": r'ute@SC5G.*\$'
}

